            writer.WriteString("message_id", messageDetail.MessageId);

            writer.WriteString("sender", messageDetail.Sender);

            writer.WritePropertyName("recipients");
            JsonSerializer.Serialize(writer, messageDetail.Recipients, jsonSerializerOptions);
            var statusRawValue = MessageDetail.StatusEnumToJsonValue(messageDetail.Status);
            writer.WriteString("status", statusRawValue);
            writer.WriteString("queued_at", messageDetail.QueuedAt.ToString(QueuedAtFormat));

            writer.WriteString("updated_at", messageDetail.UpdatedAt.ToString(UpdatedAtFormat));

            if (messageDetail.SubjectOption.IsSet)
                writer.WriteString("subject", messageDetail.Subject);

            if (messageDetail.BounceReasonOption.IsSet)
                writer.WriteString("bounce_reason", messageDetail.BounceReason);

            if (messageDetail.SizeBytesOption.IsSet)
                writer.WriteNumber("size_bytes", messageDetail.SizeBytesOption.Value!.Value);

            if (messageDetail.FromOption.IsSet)
                writer.WriteString("from", messageDetail.From);

            if (messageDetail.ToOption.IsSet)
            {
                writer.WritePropertyName("to");
                JsonSerializer.Serialize(writer, messageDetail.To, jsonSerializerOptions);
            }
            if (messageDetail.CcOption.IsSet)
            {
                writer.WritePropertyName("cc");
                JsonSerializer.Serialize(writer, messageDetail.Cc, jsonSerializerOptions);
            }
            if (messageDetail.BccOption.IsSet)
            {
                writer.WritePropertyName("bcc");
                JsonSerializer.Serialize(writer, messageDetail.Bcc, jsonSerializerOptions);
            }
            if (messageDetail.TextOption.IsSet)
                writer.WriteString("text", messageDetail.Text);

            if (messageDetail.HtmlOption.IsSet)
                writer.WriteString("html", messageDetail.Html);

            if (messageDetail.HeadersOption.IsSet)
            {
                writer.WritePropertyName("headers");
                JsonSerializer.Serialize(writer, messageDetail.Headers, jsonSerializerOptions);
            }
        }
    }
}
